<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\{Department,User};use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class DepartmentController extends Controller {public function index(Request $r){$this->authorize('viewAny',Department::class);$departments=Department::with(['hods','managers'])->withCount('assignedUsers')->orderBy('name')->paginate(20);$hods=User::whereIn('role',['HOD','Director'])->orderBy('name')->get();return view('admin.departments.index',compact('departments','hods'));}public function store(Request $r){$this->authorize('create',Department::class);$data=$r->validate(['name'=>'required|string|max:100|unique:departments','code'=>'required|string|max:30|unique:departments','active'=>'nullable|boolean','hod_ids'=>'nullable|array','hod_ids.*'=>'exists:users,id']);$d=Department::create($data+['active'=>$r->boolean('active')]);$d->hods()->sync($r->input('hod_ids',[]));return back()->with('success','Department created.');}public function update(Request $r,Department $department){$this->authorize('update',$department);$old=$department->name;$data=$r->validate(['name'=>['required','string','max:100',Rule::unique('departments')->ignore($department->id)],'code'=>['required','string','max:30',Rule::unique('departments')->ignore($department->id)],'active'=>'nullable|boolean','hod_ids'=>'nullable|array']);$department->update($data+['active'=>$r->boolean('active')]);User::where('department_id',$department->id)->update(['department'=>$data['name']]);$department->hods()->sync($r->input('hod_ids',[]));return back()->with('success','Department updated.');}public function destroy(Request $r,Department $department){$this->authorize('delete',$department);abort_if($department->assignedUsers()->exists(),422,'Move employees before deleting this department.');$department->delete();return back()->with('success','Department deleted.');}}
